[CmdletBinding()]param([string]$RepositoryRoot=(Split-Path -Parent (Split-Path -Parent $PSScriptRoot)))
Set-StrictMode -Version 2.0;$ErrorActionPreference='Stop';$pipeline=Join-Path $RepositoryRoot 'Modules\ADHealth\Invoke-MSADPTADHealthOfflineAssessment-v1.1.0.ps1';$fixture=Join-Path $RepositoryRoot 'Tests\Fixtures\ADHealthPipeline';$targets=Join-Path $fixture 'ExpectedTargets.csv';$temp=Join-Path ([IO.Path]::GetTempPath()) ('MSADPT-ADHealth-v110-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory $temp|Out-Null
try{$result=& $pipeline -EvidenceRoot $fixture -OutputRoot $temp -ExpectedTargetPath $targets;if($result.Status-ne'Succeeded'){throw 'Pipeline stage failed'};if($result.NetworkActivity-ne'None'-or$result.ActiveDirectoryQueries-ne'None'){throw 'Offline safety contract failed'};$required=@('ADHealth-Assessment.json','ADHealth-Evidence.csv','ADHealth-Coverage.csv','ADHealth-Conflicts.csv','ADHealth-StageStatus.json','MSADPT-AD-Health.html');foreach($name in $required){if(-not(Test-Path (Join-Path $temp $name))){throw "Missing output: $name"}};$a=Get-Content (Join-Path $temp 'ADHealth-Assessment.json')-Raw|ConvertFrom-Json;if($a.OverallDisposition-ne'ConfirmedUnhealthy'){throw "Expected ConfirmedUnhealthy, got $($a.OverallDisposition)"};if('DC03'-notin @($a.MissingTargets)){throw 'Missing expected DC03 was not detected'};if(@($a.Evidence|Where-Object{$_.SourceRelativePath-eq'notes.txt' -and $_.CollectionStatus-eq'Unrecognized'}).Count-ne1){throw 'Ambiguous file was not safely rejected'};$c=$a.Coverage;if($c.CoverageDisposition-ne'Partial'){throw 'Expected partial coverage'};if($c.CompletenessClaimsAllowed-ne$true){throw 'Expected-target coverage source not honored'}
[pscustomobject]@{Status='Passed';TestVersion='1.1.0';DiscoveredFileCount=$result.DiscoveredFileCount;NormalizedEvidenceCount=$result.NormalizedEvidenceCount;MissingTargetDetected=$true;AmbiguousEvidenceRejected=$true;ConfirmedFailurePreserved=$true;OutputContractValidated=$true;NetworkActivity='None';ActiveDirectoryQueries='None';RemoteChanges='None'}
}finally{Remove-Item $temp -Recurse -Force -ErrorAction SilentlyContinue}
